from base import *
body = cap("Compact · the sound bars settle to a gentle still level") + compact(bars()+'<span>Midnight Rain — Taylor Swift</span>','<span class="ring" style="--p:40%"></span><span>12:34</span>')
body += cap("Open notch · Home edit: widgets lift straight into place, no wiggle") + opened('<div style="display:flex;gap:10px">'+''.join(f'<div class="tile" style="width:130px;height:104px"><div class="q" style="font-size:11px">{a}</div><div style="font-size:14px;font-weight:600;margin-top:4px">{b}</div></div>' for a,b in [("NOW PLAYING","Midnight Rain"),("TIMER","12:34"),("SHELF","3 items"),("AGENTS","2 running")])+'</div><div class="note">Same layout, same content — motion-sensitive users get fades instead of springs, wiggles and bouncing bars.</div>')
body += cap("Settings · Appearance") + opened('<div class="card"><div style="display:flex;justify-content:space-between;font-size:13px"><span>Reduce motion is on (macOS setting)</span><span class="q">PancakeNotch follows it everywhere</span></div><div class="bar" style="margin-top:10px"><i style="width:100%"></i></div></div>', h=90)
open("m15.html","w").write(page("Honor Reduce Motion everywhere","Every view follows the macOS Reduce Motion setting — not just the few that check it today.",body))
